const canvas = document.getElementById("pendulum-canvas");
const ctx = canvas.getContext("2d");
canvas.width = 400;
canvas.height = 400;

// Define the pendulum's initial angle and angular velocity
let initialAngle = 45;
let angularVelocity = 0;

// Define the gravitational acceleration and the length of the pendulum
const g = 9.8; // m/s^2
const length = 100; // pixels

// Define the simulation's time step and maximum velocity
const dt = 0.01; // seconds
const maxVelocity = 20; // pixels per second

// Define the pendulum's position and velocity
let)x = length * Math.sin(Math.PI / 180 * initialAngle);
let y = -length * Math.cos(Math.PI / 180 * initialAngle);
let velocityX = 0;
let velocityY = 0;

// Define the release button
const releaseButton = document.getElementById("release-button");

// Main simulation loop
function simulate() {
  // Update the pendulum's position and velocity using the equations of motion
  angularVelocity += g / length * Math.sin(Math.PI / 180 * initialAngle) * dt;
  x += velocityX * dt;
  y += velocityY * dt;
  velocityX = angularVelocity * length;
  velocityY = -angularVelocity * length;

  // Limit the velocity to prevent numerical instability
  if (Math.abs(velocityX) > maxVelocity) {
    velocityX = Math.sign(velocityX) * maxVelocity;
  }
  if (Math.abs(velocityY) > maxVelocity) {
    velocityY = Math.sign(velocityY) * maxVelocity;
  }

  // Check if the pendulum has stopped swinging
  if (Math.abs(angularVelocity) < 0.01 && Math.abs(velocityX) < 0.01 && Math.abs(velocityY) < 0.01) {
    stopSimulation();
  }

  // Render the pendulum
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(x, y, 10, 0, 2 * Math.PI);
  ctx.fillStyle = "black";
  ctx.fill();
}

// Start the simulation when the release button is clicked
releaseButton.addEventListener("click", () => {
  initialAngle = (document.getElementById("initial-angle").value * Math.PI) / 180;
  angularVelocity = 0;
  x = length * Math.sin(Math.PI / 180 * initialAngle);
  y = -length * Math.cos(Math.PI / 180 * initialAngle);
  velocityX = 0;
  velocityY = 0;
  simulate();
});

// Stop the simulation when the pendulum stops swinging
function stopSimulation() {
  releaseButton.disabled = true;
}

// Animation loop
